/* @lc app=leetcode id=2538 lang=kotlin */
class Solution { fun maxOutput(n: Int, edges: Array<IntArray>, price: IntArray): Long = Array(n) { mutableListOf<Int>() }.apply { edges.forEach { e -> this[e[0]].add(e[1]).also { this[e[1]].add(e[0]) } } }.let { adj -> longArrayOf(0L).let { ans -> kotlin.DeepRecursiveFunction<Pair<Int, Int>, LongArray> { (u, p) -> longArrayOf(price[u].toLong(), 0L).let { state -> state.also { adj[u].forEach { v -> if (v != p) callRecursive(v to u).let { child -> ans[0] = maxOf(ans[0], maxOf(state[0] + child[1], state[1] + child[0])).run { state[0] = maxOf(state[0], child[0] + price[u]) }.run { state[1] = maxOf(state[1], child[1] + price[u]) } } } } } }.callRecursive(0 to -1).run { ans[0] } } } }